package cn.xunxu.core;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static cn.xunxu.core.GraphService.*;
import org.junit.jupiter.api.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import cn.xunxu.core.GraphRepository.Graph;
import java.util.*;
import java.util.function.Function;

class GraphRulesTest {
  Graph graph;GraphRepository repository;GraphService service;AiClient ai;String root;String space;
  @BeforeEach @SuppressWarnings("unchecked") void setup(){graph=new Graph();repository=mock(GraphRepository.class);ai=mock(AiClient.class);var mapper=new ObjectMapper();when(repository.write(any())).thenAnswer(inv->{Object result=((Function<Graph,Object>)inv.getArgument(0)).apply(graph);graph.revision++;return result;});when(repository.read(any())).thenAnswer(inv->((Function<Graph,Object>)inv.getArgument(0)).apply(graph));when(repository.encode(any())).thenAnswer(inv->mapper.writeValueAsString(inv.getArgument(0)));when(repository.decode(anyString())).thenAnswer(inv->mapper.readValue((String)inv.getArgument(0),Map.class));service=new GraphService(repository,ai);var sp=obj(service.createSpace(map("title","研究目标","goal","ROOT_CONTEXT")));root=s(sp,"root_id");space=s(sp,"id");}
  Map<String,Object> child(String parent,String title){return obj(service.createNode(map("parent_id",parent,"title",title,"summary",title+"_DIRECT")));}
  Map<String,Object> commit(String op,String node,Object...args){var d=map("operation",op,"node_id",node,"reason","人工确定操作");d.putAll(map(args));var p=obj(service.propose(d));return obj(service.approve(s(p,"id")));}
  @Test void pathContextNeverRollsUpChildren(){var p=child(root,"PARENT");var ch=child(s(p,"id"),"CHILD_RESULTS");child(root,"SIBLING_SECRET");var c=obj(service.context(s(p,"id")));assertEquals("PARENT_DIRECT",c.get("direct"));assertEquals(1,objects(c.get("ancestors")).size());assertFalse(c.toString().contains("CHILD_RESULTS"));assertFalse(c.toString().contains("SIBLING_SECRET"));}
  @Test void confluencePreservesOriginalSubtrees(){var a=child(root,"A");var b=child(root,"B");var c=child(s(a,"id"),"A_CHILD");var p=commit("confluence",s(a,"id"),"sources",List.of(a.get("id"),b.get("id")),"title","联合新问题");var joined=graph.get("nodes",s(p,"result_node_id"));assertNull(joined.get("parent_id"));assertEquals(a.get("id"),c.get("parent_id"));assertEquals(2,strings(joined,"sources").size());assertEquals(2,graph.all("relations").size());var descendant=child(s(joined,"id"),"联合后续研究");assertEquals(2,objects(obj(service.context(s(descendant,"id"))).get("sources")).size());}
  @Test void staleApprovalsAndCyclesRejected(){var a=child(root,"A");var b=child(root,"B");var ch=child(s(a,"id"),"C");assertThrows(IllegalArgumentException.class,()->service.propose(map("operation","move","node_id",a.get("id"),"target_id",ch.get("id"),"reason","循环")));var p=obj(service.propose(map("operation","move","node_id",ch.get("id"),"target_id",b.get("id"),"reason","重新归属")));child(root,"OTHER");assertThrows(IllegalArgumentException.class,()->service.approve(s(p,"id")));assertEquals(a.get("id"),ch.get("parent_id"));}
  @Test void leafMergeRetainsHistoricalIdentities(){var a=child(root,"A");var b=child(root,"B");var p=commit("merge",s(a,"id"),"target_id",b.get("id"),"title","合并研究");assertTrue(flag(a,"archived"));assertTrue(flag(b,"archived"));assertEquals(p.get("result_node_id"),a.get("merged_into"));var saved=new ArrayList<>(graph.all("audit")).get(graph.all("audit").size()-1);assertFalse(obj(saved.get("undo_snapshot")).containsKey("audit"));var nonleaf=child(root,"NONLEAF");child(s(nonleaf,"id"),"DESCENDANT");assertThrows(IllegalArgumentException.class,()->service.propose(map("operation","merge","node_id",nonleaf.get("id"),"target_id",p.get("result_node_id"),"reason","不能合并")));}
  @Test void frozenBranchesRemainReferencesButCannotGrow(){var a=child(root,"A");var b=child(s(a,"id"),"B");commit("freeze",s(a,"id"));assertThrows(IllegalArgumentException.class,()->child(s(b,"id"),"NO_GROWTH"));commit("unfreeze",s(a,"id"));commit("hide",s(a,"id"));assertTrue(flag(b,"hidden"));child(s(b,"id"),"HIDDEN_GROWTH");commit("restore",s(a,"id"));assertFalse(flag(b,"hidden"));}
  @Test void transplantPreservesOriginAndExcludesSiblings(){var a=child(root,"BRANCH");child(root,"SECRET_SIBLING");var child=child(s(a,"id"),"CHILD_OUTCOME");var conv=obj(service.conversation(map("node_id",a.get("id"))));var p=commit("transplant",s(a,"id"),"title","独立空间");assertEquals(a.get("id"),conv.get("anchor_id"));assertEquals(space,conv.get("space_id"));assertNull(a.get("parent_id"));assertEquals(p.get("result_space_id"),child.get("space_id"));String nutrient=service.transplantContext(s(p,"transplant_id"));assertTrue(nutrient.contains("ROOT_CONTEXT"));assertFalse(nutrient.contains("SECRET_SIBLING"));assertFalse(nutrient.contains("CHILD_OUTCOME_DIRECT"));}
  @Test void runEventsAreIdempotentAndDoNotChangeRootSummary(){var n=obj(service.createNode(map("parent_id",root,"title","实验","kind","action","summary","实验设计")));var run=obj(service.createRun(map("node_id",n.get("id"))));var ev=map("event_id","start","status","running","sequence",1);assertEquals(service.report(s(run,"id"),ev),service.report(s(run,"id"),ev));assertThrows(IllegalArgumentException.class,()->service.report(s(run,"id"),map("event_id","old","sequence",1,"status","running")));service.report(s(run,"id"),map("event_id","failed","status","failed","result",map("error","timeout")));var retry=obj(service.createRun(map("node_id",n.get("id"),"retry_of",run.get("id"))));assertNotEquals(run.get("id"),retry.get("id"));assertEquals("ROOT_CONTEXT",obj(service.context(root)).get("direct"));}
}
